-- Question content is immutable after import so existing exam answers stay valid.
CREATE TABLE learning_packs (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, track TEXT NOT NULL, bank TEXT NOT NULL,
  provider TEXT NOT NULL, year INTEGER, period TEXT NOT NULL, available_at INTEGER NOT NULL,
  is_sample INTEGER NOT NULL CHECK (is_sample IN (0, 1)), attribution TEXT NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)), created_at INTEGER NOT NULL
);
CREATE INDEX learning_packs_release_idx ON learning_packs (track, is_active, available_at);
CREATE TABLE learning_questions (
  id TEXT PRIMARY KEY, pack_id TEXT NOT NULL REFERENCES learning_packs(id),
  subject_id TEXT NOT NULL, chapter TEXT NOT NULL, difficulty TEXT NOT NULL CHECK (difficulty IN ('easy', 'medium', 'hard')),
  content TEXT NOT NULL CHECK (json_valid(content))
);
CREATE INDEX learning_questions_filter_idx ON learning_questions (pack_id, subject_id, chapter, difficulty);
CREATE TABLE learning_attempts (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  track TEXT NOT NULL, mode TEXT NOT NULL CHECK (mode IN ('practice', 'exam')),
  started_at INTEGER NOT NULL, finished_at INTEGER
);
CREATE INDEX learning_attempts_user_idx ON learning_attempts (user_id, started_at DESC);
CREATE TABLE learning_answers (
  attempt_id TEXT NOT NULL REFERENCES learning_attempts(id) ON DELETE CASCADE,
  question_id TEXT NOT NULL REFERENCES learning_questions(id), ordinal INTEGER NOT NULL,
  selected_index INTEGER CHECK (selected_index BETWEEN 0 AND 3), answered_at INTEGER,
  PRIMARY KEY (attempt_id, question_id), UNIQUE(attempt_id, ordinal)
);
CREATE INDEX learning_answers_question_idx ON learning_answers (question_id, attempt_id);
CREATE TABLE learning_annotations (
  user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  question_id TEXT NOT NULL REFERENCES learning_questions(id),
  saved INTEGER NOT NULL CHECK (saved IN (0, 1)), note TEXT NOT NULL DEFAULT '', highlight TEXT NOT NULL DEFAULT '',
  updated_at INTEGER NOT NULL, PRIMARY KEY (user_id, question_id)
);
CREATE TABLE learning_reviews (
  user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  question_id TEXT NOT NULL REFERENCES learning_questions(id),
  due_at INTEGER NOT NULL, interval_days INTEGER NOT NULL CHECK (interval_days BETWEEN 1 AND 60),
  repetitions INTEGER NOT NULL DEFAULT 1, PRIMARY KEY (user_id, question_id)
);
CREATE INDEX learning_reviews_due_idx ON learning_reviews(user_id, due_at);
CREATE TABLE learning_scores (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  provider TEXT NOT NULL, title TEXT NOT NULL, exam_date TEXT NOT NULL,
  score REAL NOT NULL CHECK (score BETWEEN 0 AND 20000), notes TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE INDEX learning_scores_user_idx ON learning_scores(user_id, exam_date DESC);
CREATE TABLE learning_prep (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  content TEXT NOT NULL CHECK(json_valid(content)), created_at INTEGER NOT NULL
);
CREATE INDEX learning_prep_user_idx ON learning_prep(user_id, created_at DESC);
CREATE TABLE learning_messages (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK(role IN ('user', 'assistant')), content TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE INDEX learning_messages_user_idx ON learning_messages(user_id, created_at DESC);
CREATE TABLE learning_ai_usage (
  user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  hour INTEGER NOT NULL, requests INTEGER NOT NULL, PRIMARY KEY(user_id, hour)
);
UPDATE system_metadata SET value = '8', updated_at = unixepoch() WHERE key = 'schema_version';

-- Clearly labelled original samples. Excluded from practice unless explicitly selected.
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('sample-konkur-cells','آشنایی با سلول · نمونهٔ آموزشی','konkur','authored','authored',NULL,'نمونه',1767225600000,1,'پنج سؤال تألیفی نمونه برای آزمایش قابلیت‌های برنامه؛ برگرفته از آزمون رسمی یا مؤسسه نیست.',1767225600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('sample-konkur-cells-1','sample-konkur-cells','biology','سلول و اندامک‌ها','easy','{"key":"cell-1","subjectId":"biology","chapter":"سلول و اندامک‌ها","prompt":"کدام ساختار به‌طور مستقیم در ساخت پروتئین نقش دارد؟","options":["ریبوزوم","لیزوزوم","واکوئل","دیوارهٔ سلولی"],"correctIndex":0,"explanation":"ریبوزوم محل ترجمه و ساخت زنجیرهٔ پلی‌پپتیدی بر اساس اطلاعات RNA پیام‌رسان است.","difficulty":"easy","topic":{"title":"ساختار و کار سلول","important":["ریبوزوم محل ساخت پروتئین است.","غشای سلول ساختار دولایهٔ فسفولیپیدی دارد.","کلروپلاست محل فتوسنتز در سلول گیاهی است."],"microLesson":"سلول واحد ساختاری و عملکردی جانداران است. غشا تبادل مواد را تنظیم می‌کند. ریبوزوم‌ها پروتئین می‌سازند و میتوکندری در تنفس هوازی و تولید ATP نقش دارد. سلول گیاهی علاوه بر این‌ها می‌تواند کلروپلاست و دیوارهٔ سلولی داشته باشد. مادهٔ وراثتی از نوکلئوتیدها ساخته شده است.","branches":[{"title":"ساخت پروتئین","points":["ریبوزوم","استفاده از اطلاعات RNA پیام‌رسان"]},{"title":"تبدیل انرژی","points":["میتوکندری: تنفس سلولی","کلروپلاست: فتوسنتز"]},{"title":"مرز سلول","points":["دولایهٔ فسفولیپیدی","پروتئین‌های غشایی"]},{"title":"اطلاعات وراثتی","points":["DNA","واحد سازنده: نوکلئوتید"]}]}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('sample-konkur-cells-2','sample-konkur-cells','biology','سلول و اندامک‌ها','easy','{"key":"cell-2","subjectId":"biology","chapter":"سلول و اندامک‌ها","prompt":"کدام اندامک در تنفس هوازی سلول‌های یوکاریوتی نقش اصلی دارد؟","options":["دستگاه گلژی","میتوکندری","هستک","لیزوزوم"],"correctIndex":1,"explanation":"بخش مهمی از مراحل تنفس هوازی، از جمله چرخهٔ کربس و زنجیرهٔ انتقال الکترون، در میتوکندری انجام می‌شود.","difficulty":"easy","topic":{"title":"ساختار و کار سلول","important":["ریبوزوم محل ساخت پروتئین است.","غشای سلول ساختار دولایهٔ فسفولیپیدی دارد.","کلروپلاست محل فتوسنتز در سلول گیاهی است."],"microLesson":"سلول واحد ساختاری و عملکردی جانداران است. غشا تبادل مواد را تنظیم می‌کند. ریبوزوم‌ها پروتئین می‌سازند و میتوکندری در تنفس هوازی و تولید ATP نقش دارد. سلول گیاهی علاوه بر این‌ها می‌تواند کلروپلاست و دیوارهٔ سلولی داشته باشد. مادهٔ وراثتی از نوکلئوتیدها ساخته شده است.","branches":[{"title":"ساخت پروتئین","points":["ریبوزوم","استفاده از اطلاعات RNA پیام‌رسان"]},{"title":"تبدیل انرژی","points":["میتوکندری: تنفس سلولی","کلروپلاست: فتوسنتز"]},{"title":"مرز سلول","points":["دولایهٔ فسفولیپیدی","پروتئین‌های غشایی"]},{"title":"اطلاعات وراثتی","points":["DNA","واحد سازنده: نوکلئوتید"]}]}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('sample-konkur-cells-3','sample-konkur-cells','biology','سلول و اندامک‌ها','medium','{"key":"cell-3","subjectId":"biology","chapter":"سلول و اندامک‌ها","prompt":"ساختار پایهٔ غشای سلول را کدام مورد تشکیل می‌دهد؟","options":["یک لایهٔ سلولزی","دو لایهٔ پروتئینی بدون لیپید","دولایهٔ فسفولیپیدی همراه پروتئین‌ها","یک لایهٔ DNA"],"correctIndex":2,"explanation":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌های همراه آن تشکیل شده است؛ این ساختار را با مدل موزاییک سیال توصیف می‌کنند.","difficulty":"medium","topic":{"title":"ساختار و کار سلول","important":["ریبوزوم محل ساخت پروتئین است.","غشای سلول ساختار دولایهٔ فسفولیپیدی دارد.","کلروپلاست محل فتوسنتز در سلول گیاهی است."],"microLesson":"سلول واحد ساختاری و عملکردی جانداران است. غشا تبادل مواد را تنظیم می‌کند. ریبوزوم‌ها پروتئین می‌سازند و میتوکندری در تنفس هوازی و تولید ATP نقش دارد. سلول گیاهی علاوه بر این‌ها می‌تواند کلروپلاست و دیوارهٔ سلولی داشته باشد. مادهٔ وراثتی از نوکلئوتیدها ساخته شده است.","branches":[{"title":"ساخت پروتئین","points":["ریبوزوم","استفاده از اطلاعات RNA پیام‌رسان"]},{"title":"تبدیل انرژی","points":["میتوکندری: تنفس سلولی","کلروپلاست: فتوسنتز"]},{"title":"مرز سلول","points":["دولایهٔ فسفولیپیدی","پروتئین‌های غشایی"]},{"title":"اطلاعات وراثتی","points":["DNA","واحد سازنده: نوکلئوتید"]}]}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('sample-konkur-cells-4','sample-konkur-cells','biology','سلول و اندامک‌ها','easy','{"key":"cell-4","subjectId":"biology","chapter":"سلول و اندامک‌ها","prompt":"واحد سازندهٔ DNA کدام است؟","options":["آمینواسید","اسید چرب","گلوکز","نوکلئوتید"],"correctIndex":3,"explanation":"DNA پلیمر نوکلئوتیدی است. هر نوکلئوتید آن دارای قند دئوکسی‌ریبوز، گروه فسفات و باز نیتروژن‌دار است.","difficulty":"easy","topic":{"title":"ساختار و کار سلول","important":["ریبوزوم محل ساخت پروتئین است.","غشای سلول ساختار دولایهٔ فسفولیپیدی دارد.","کلروپلاست محل فتوسنتز در سلول گیاهی است."],"microLesson":"سلول واحد ساختاری و عملکردی جانداران است. غشا تبادل مواد را تنظیم می‌کند. ریبوزوم‌ها پروتئین می‌سازند و میتوکندری در تنفس هوازی و تولید ATP نقش دارد. سلول گیاهی علاوه بر این‌ها می‌تواند کلروپلاست و دیوارهٔ سلولی داشته باشد. مادهٔ وراثتی از نوکلئوتیدها ساخته شده است.","branches":[{"title":"ساخت پروتئین","points":["ریبوزوم","استفاده از اطلاعات RNA پیام‌رسان"]},{"title":"تبدیل انرژی","points":["میتوکندری: تنفس سلولی","کلروپلاست: فتوسنتز"]},{"title":"مرز سلول","points":["دولایهٔ فسفولیپیدی","پروتئین‌های غشایی"]},{"title":"اطلاعات وراثتی","points":["DNA","واحد سازنده: نوکلئوتید"]}]}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('sample-konkur-cells-5','sample-konkur-cells','biology','سلول و اندامک‌ها','medium','{"key":"cell-5","subjectId":"biology","chapter":"سلول و اندامک‌ها","prompt":"فتوسنتز در سلول گیاهی در کدام اندامک انجام می‌شود؟","options":["کلروپلاست","میتوکندری","ریبوزوم","دستگاه گلژی"],"correctIndex":0,"explanation":"کلروپلاست دارای رنگیزه‌های فتوسنتزی است. واکنش‌های نوری در غشای تیلاکوئید و چرخهٔ کالوین در بسترهٔ آن انجام می‌شوند.","difficulty":"medium","topic":{"title":"ساختار و کار سلول","important":["ریبوزوم محل ساخت پروتئین است.","غشای سلول ساختار دولایهٔ فسفولیپیدی دارد.","کلروپلاست محل فتوسنتز در سلول گیاهی است."],"microLesson":"سلول واحد ساختاری و عملکردی جانداران است. غشا تبادل مواد را تنظیم می‌کند. ریبوزوم‌ها پروتئین می‌سازند و میتوکندری در تنفس هوازی و تولید ATP نقش دارد. سلول گیاهی علاوه بر این‌ها می‌تواند کلروپلاست و دیوارهٔ سلولی داشته باشد. مادهٔ وراثتی از نوکلئوتیدها ساخته شده است.","branches":[{"title":"ساخت پروتئین","points":["ریبوزوم","استفاده از اطلاعات RNA پیام‌رسان"]},{"title":"تبدیل انرژی","points":["میتوکندری: تنفس سلولی","کلروپلاست: فتوسنتز"]},{"title":"مرز سلول","points":["دولایهٔ فسفولیپیدی","پروتئین‌های غشایی"]},{"title":"اطلاعات وراثتی","points":["DNA","واحد سازنده: نوکلئوتید"]}]}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('sample-medical-biochemistry','مولکول‌های زیستی · نمونهٔ آموزشی','medical-basics','authored','authored',NULL,'نمونه',1767225600000,1,'پنج سؤال تألیفی نمونه برای آزمایش قابلیت‌های برنامه؛ سؤال آزمون رسمی نیست.',1767225600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('sample-medical-biochemistry-1','sample-medical-biochemistry','biochemistry','مولکول‌های زیستی','easy','{"key":"biochem-1","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"ویژگی مهم مولکول آب که در حلالیت بسیاری از ترکیبات زیستی نقش دارد چیست؟","options":["غیرقطبی بودن","قطبی بودن","نداشتن پیوند کووالانسی","نداشتن الکترون"],"correctIndex":1,"explanation":"توزیع نامتقارن بار و شکل خمیدهٔ مولکول آب باعث قطبی بودن آن می‌شود. این ویژگی در برهم‌کنش با یون‌ها و مولکول‌های قطبی نقش دارد.","difficulty":"easy","topic":{"title":"مولکول‌های زیستی","important":["آنزیم‌ها انرژی فعال‌سازی را کاهش می‌دهند.","پیوند پپتیدی، آمینواسیدها را به هم متصل می‌کند.","RNA معمولاً دارای اوراسیل و DNA دارای تیمین است."],"microLesson":"مولکول‌های زیستی شامل پروتئین‌ها، اسیدهای نوکلئیک، کربوهیدرات‌ها و لیپیدها هستند. پروتئین‌ها از آمینواسیدها و اسیدهای نوکلئیک از نوکلئوتیدها ساخته می‌شوند. آب مولکولی قطبی است. آنزیم‌ها سرعت واکنش را با کاهش انرژی فعال‌سازی افزایش می‌دهند. ATP در انتقال انرژی در سلول نقش دارد.","branches":[{"title":"پروتئین","points":["مونومر: آمینواسید","اتصال: پیوند پپتیدی"]},{"title":"اسید نوکلئیک","points":["مونومر: نوکلئوتید","RNA: اوراسیل؛ DNA: تیمین"]},{"title":"کاتالیز","points":["آنزیم","کاهش انرژی فعال‌سازی"]},{"title":"آب و انرژی","points":["قطبیت آب","ATP: آدنوزین و سه گروه فسفات"]}]}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('sample-medical-biochemistry-2','sample-medical-biochemistry','biochemistry','مولکول‌های زیستی','medium','{"key":"biochem-2","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"آنزیم‌ها چگونه سرعت واکنش را افزایش می‌دهند؟","options":["با افزایش انرژی فعال‌سازی","با تغییر همیشگی ثابت تعادل","با کاهش انرژی فعال‌سازی","با مصرف کامل در هر واکنش"],"correctIndex":2,"explanation":"آنزیم مسیر واکنشی با انرژی فعال‌سازی کمتر فراهم می‌کند. کاتالیزور ثابت تعادل و اختلاف انرژی آزاد واکنش را تغییر نمی‌دهد.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آنزیم‌ها انرژی فعال‌سازی را کاهش می‌دهند.","پیوند پپتیدی، آمینواسیدها را به هم متصل می‌کند.","RNA معمولاً دارای اوراسیل و DNA دارای تیمین است."],"microLesson":"مولکول‌های زیستی شامل پروتئین‌ها، اسیدهای نوکلئیک، کربوهیدرات‌ها و لیپیدها هستند. پروتئین‌ها از آمینواسیدها و اسیدهای نوکلئیک از نوکلئوتیدها ساخته می‌شوند. آب مولکولی قطبی است. آنزیم‌ها سرعت واکنش را با کاهش انرژی فعال‌سازی افزایش می‌دهند. ATP در انتقال انرژی در سلول نقش دارد.","branches":[{"title":"پروتئین","points":["مونومر: آمینواسید","اتصال: پیوند پپتیدی"]},{"title":"اسید نوکلئیک","points":["مونومر: نوکلئوتید","RNA: اوراسیل؛ DNA: تیمین"]},{"title":"کاتالیز","points":["آنزیم","کاهش انرژی فعال‌سازی"]},{"title":"آب و انرژی","points":["قطبیت آب","ATP: آدنوزین و سه گروه فسفات"]}]}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('sample-medical-biochemistry-3','sample-medical-biochemistry','biochemistry','مولکول‌های زیستی','easy','{"key":"biochem-3","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"پیوند میان آمینواسیدهای مجاور در زنجیرهٔ پروتئینی چه نام دارد؟","options":["گلیکوزیدی","فسفودی‌استر","هیدروژنی","پپتیدی"],"correctIndex":3,"explanation":"پیوند پپتیدی نوعی پیوند آمیدی میان گروه کربوکسیل یک آمینواسید و گروه آمین آمینواسید دیگر است.","difficulty":"easy","topic":{"title":"مولکول‌های زیستی","important":["آنزیم‌ها انرژی فعال‌سازی را کاهش می‌دهند.","پیوند پپتیدی، آمینواسیدها را به هم متصل می‌کند.","RNA معمولاً دارای اوراسیل و DNA دارای تیمین است."],"microLesson":"مولکول‌های زیستی شامل پروتئین‌ها، اسیدهای نوکلئیک، کربوهیدرات‌ها و لیپیدها هستند. پروتئین‌ها از آمینواسیدها و اسیدهای نوکلئیک از نوکلئوتیدها ساخته می‌شوند. آب مولکولی قطبی است. آنزیم‌ها سرعت واکنش را با کاهش انرژی فعال‌سازی افزایش می‌دهند. ATP در انتقال انرژی در سلول نقش دارد.","branches":[{"title":"پروتئین","points":["مونومر: آمینواسید","اتصال: پیوند پپتیدی"]},{"title":"اسید نوکلئیک","points":["مونومر: نوکلئوتید","RNA: اوراسیل؛ DNA: تیمین"]},{"title":"کاتالیز","points":["آنزیم","کاهش انرژی فعال‌سازی"]},{"title":"آب و انرژی","points":["قطبیت آب","ATP: آدنوزین و سه گروه فسفات"]}]}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('sample-medical-biochemistry-4','sample-medical-biochemistry','biochemistry','مولکول‌های زیستی','easy','{"key":"biochem-4","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"کدام باز در RNA معمولی به جای تیمین قرار دارد؟","options":["اوراسیل","گوانین","آدنین","سیتوزین"],"correctIndex":0,"explanation":"در RNA معمولاً اوراسیل حضور دارد، در حالی که در DNA تیمین جای آن را می‌گیرد. آدنین، گوانین و سیتوزین در هر دو وجود دارند.","difficulty":"easy","topic":{"title":"مولکول‌های زیستی","important":["آنزیم‌ها انرژی فعال‌سازی را کاهش می‌دهند.","پیوند پپتیدی، آمینواسیدها را به هم متصل می‌کند.","RNA معمولاً دارای اوراسیل و DNA دارای تیمین است."],"microLesson":"مولکول‌های زیستی شامل پروتئین‌ها، اسیدهای نوکلئیک، کربوهیدرات‌ها و لیپیدها هستند. پروتئین‌ها از آمینواسیدها و اسیدهای نوکلئیک از نوکلئوتیدها ساخته می‌شوند. آب مولکولی قطبی است. آنزیم‌ها سرعت واکنش را با کاهش انرژی فعال‌سازی افزایش می‌دهند. ATP در انتقال انرژی در سلول نقش دارد.","branches":[{"title":"پروتئین","points":["مونومر: آمینواسید","اتصال: پیوند پپتیدی"]},{"title":"اسید نوکلئیک","points":["مونومر: نوکلئوتید","RNA: اوراسیل؛ DNA: تیمین"]},{"title":"کاتالیز","points":["آنزیم","کاهش انرژی فعال‌سازی"]},{"title":"آب و انرژی","points":["قطبیت آب","ATP: آدنوزین و سه گروه فسفات"]}]}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('sample-medical-biochemistry-5','sample-medical-biochemistry','biochemistry','مولکول‌های زیستی','easy','{"key":"biochem-5","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"ATP دارای چند گروه فسفات است؟","options":["یک","دو","سه","چهار"],"correctIndex":2,"explanation":"ATP مخفف آدنوزین تری‌فسفات و دارای سه گروه فسفات است. انتقال و هیدرولیز گروه‌های فسفات آن با انتقال انرژی در سلول ارتباط دارد.","difficulty":"easy","topic":{"title":"مولکول‌های زیستی","important":["آنزیم‌ها انرژی فعال‌سازی را کاهش می‌دهند.","پیوند پپتیدی، آمینواسیدها را به هم متصل می‌کند.","RNA معمولاً دارای اوراسیل و DNA دارای تیمین است."],"microLesson":"مولکول‌های زیستی شامل پروتئین‌ها، اسیدهای نوکلئیک، کربوهیدرات‌ها و لیپیدها هستند. پروتئین‌ها از آمینواسیدها و اسیدهای نوکلئیک از نوکلئوتیدها ساخته می‌شوند. آب مولکولی قطبی است. آنزیم‌ها سرعت واکنش را با کاهش انرژی فعال‌سازی افزایش می‌دهند. ATP در انتقال انرژی در سلول نقش دارد.","branches":[{"title":"پروتئین","points":["مونومر: آمینواسید","اتصال: پیوند پپتیدی"]},{"title":"اسید نوکلئیک","points":["مونومر: نوکلئوتید","RNA: اوراسیل؛ DNA: تیمین"]},{"title":"کاتالیز","points":["آنزیم","کاهش انرژی فعال‌سازی"]},{"title":"آب و انرژی","points":["قطبیت آب","ATP: آدنوزین و سه گروه فسفات"]}]}}');
